import {shoeMesh,rotatePoint} from './chapter-shoes.js?v=motion-v70';
import {rasterSurface,putSurface} from './raster-surface.js?v=motion-v70';
let buffer,tint;
const rgb=s=>[1,3,5].map(i=>parseInt(s.slice(i,i+2),16));
// Preserve every original face, color, material and grain value. Added faces only close the tiny upper/sole join.
export function sealedShoeMesh(color='#232426',spikeLength=.28){const original=shoeMesh('spikes',color,'#111214','#191a1c',spikeLength),faces=original.map(face=>({...face,p:face.p.map(p=>[...p])}));const N=30,M=18;for(let i=0;i<N;i++)for(const j of [0,M-1]){const x=-1.46+i/N*2.94,X=-1.46+(i+1)/N*2.94;const candidates=original.filter(f=>f.material==='leather'&&f.p.length===4&&Math.abs(f.p[0][0]-x)<1e-8&&Math.abs(f.p[1][0]-X)<1e-8);const face=j===0?candidates[0]:candidates.at(-1);if(!face)continue;const edge=j===0?[face.p[0],face.p[1]]:[face.p[3],face.p[2]],lower=p=>[p[0],p[1]-.025,p[2]];faces.push({p:[edge[0],edge[1],lower(edge[1]),lower(edge[0])],color,material:'leather',grain:1,repair:'upper-sole-seal'});}return faces;}
export function solidShoeTriangles(o={}){const mesh=sealedShoeMesh(o.color||'#232426',o.spikeLength??.28),triangles=[],pose={yaw:o.yaw??-90,pitch:o.pitch??12,roll:o.roll??0},size=o.size??650,project=([x,y,z])=>{const k=6/(6-z*.17);return [(o.x??480)+x*size/3*k,(o.y??270)-y*size/3*k,z]};for(const face of mesh){const v=face.p.map(p=>rotatePoint(rotatePoint(p,{yaw:pose.yaw}),{pitch:pose.pitch,roll:pose.roll}));for(let i=1;i<v.length-1;i++){const a=v[0],b=v[i],c=v[i+1],ab=b.map((x,k)=>x-a[k]),ac=c.map((x,k)=>x-a[k]),n=[ab[1]*ac[2]-ab[2]*ac[1],ab[2]*ac[0]-ab[0]*ac[2],ab[0]*ac[1]-ab[1]*ac[0]],len=Math.hypot(...n)||1,diffuse=Math.abs(n[0]*-.3+n[1]*.75+n[2]*.6)/len,glint=Math.pow(Math.abs(n[0]*.15+n[1]*.5+n[2]*.85)/len,18)*(face.material==='leather'?.09:.025),light=(.34+diffuse*.62+glint)*(face.grain??1),metal=face.material==='metal';let color=rgb(face.color);triangles.push({points:[project(a),project(b),project(c)].map((p,j)=>[...p,(face.p[[0,i,i+1][j]][0]+1.4)/2.8,(face.p[[0,i,i+1][j]][2]+.6)/1.2]),color,grain:0,shade:light*(o.brightness??1)});}}return triangles;}
export function paintSolidShoe(c,o={}){buffer||=Object.assign(document.createElement('canvas'),{width:960,height:540});tint||=Object.assign(document.createElement('canvas'),{width:960,height:540});putSurface(buffer,rasterSurface(960,540,solidShoeTriangles(o)));if(o.outlineWidth>0){const t=tint.getContext('2d');t.clearRect(0,0,960,540);t.globalCompositeOperation='source-over';t.drawImage(buffer,0,0);t.globalCompositeOperation='source-in';t.fillStyle=o.outline||'#7185aa';t.fillRect(0,0,960,540);t.globalCompositeOperation='source-over';for(let i=0;i<24;i++){const a=i/24*Math.PI*2;c.drawImage(tint,Math.cos(a)*o.outlineWidth,Math.sin(a)*o.outlineWidth)}}c.drawImage(buffer,0,0);}
